package com.vahotel.web;
import com.vahotel.model.*;import com.vahotel.repo.*;import com.vahotel.service.*;import java.math.BigDecimal;import java.time.LocalDate;import org.springframework.security.core.Authentication;import org.springframework.security.web.csrf.CsrfToken;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class CustomerController {private final AccountRepository accounts;private final RoomRepository rooms;private final ReservationRepository reservations;private final PaymentRecordRepository paymentRecords;private final ReservationService service;private final PaymentService payment;private final CustomerReportRepository reports;private final EmailNotificationService email;
 public CustomerController(AccountRepository a,RoomRepository r,ReservationRepository b,PaymentRecordRepository paymentRecords,ReservationService s,PaymentService p,CustomerReportRepository cr,EmailNotificationService email){accounts=a;rooms=r;reservations=b;this.paymentRecords=paymentRecords;service=s;payment=p;reports=cr;this.email=email;}
 @GetMapping("/customer/dashboard") public String dashboard(Authentication auth,Model m,CsrfToken csrfToken,jakarta.servlet.http.HttpSession session,@RequestParam(name="notifications",defaultValue="false") boolean openNotifications){csrfToken.getToken();boolean signedInCustomer=auth!=null&&auth.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_CUSTOMER"));boolean registrationPending=false;String email=signedInCustomer?auth.getName():(String)session.getAttribute("registrationPendingDashboardEmail");if(email==null)return "redirect:/login";Account a=accounts.findByEmail(email).orElse(null);if(a==null)return "redirect:/login";if(!signedInCustomer){if(a.isEnabled()||!a.isEmailVerified()||a.getIdentityDocumentPath()==null){session.removeAttribute("registrationPendingDashboardEmail");return "redirect:/login?registrationApproved";}registrationPending=true;}var bookings=registrationPending?java.util.List.<Reservation>of():reservations.findByCustomerIdOrderByCheckInDesc(a.getId());var notices=new java.util.ArrayList<String>();if(registrationPending)notices.add("Your email and identity document have been submitted. Your account is waiting for hotel management approval.");else if(auth!=null&&auth.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_SUPER_ADMIN")))notices.add("You are viewing the customer portal with your Super Admin account.");else if(a.isEnabled())notices.add("Your customer account is approved and active.");for(Reservation b:bookings){if("PENDING".equals(b.getStatus()))notices.add("Reservation #"+b.getId()+" is waiting for manager review.");else if("APPROVED".equals(b.getStatus()))notices.add("Reservation #"+b.getId()+" is approved.");else if("REJECTED".equals(b.getStatus()))notices.add("Reservation #"+b.getId()+" was not approved. Contact management if you need help.");else if("CANCELLATION_REQUESTED".equals(b.getStatus()))notices.add("Cancellation request for reservation #"+b.getId()+" is under review.");if(b.getRequestedCheckOut()!=null)notices.add("Extension request for reservation #"+b.getId()+" is under review.");if(b.isEarlyCheckoutRequested())notices.add("Early checkout request for reservation #"+b.getId()+" is under review.");if(b.getRequestedUpgradeRoomId()!=null)notices.add("Room upgrade request for reservation #"+b.getId()+" is under review.");}m.addAttribute("account",a);m.addAttribute("reservations",bookings);m.addAttribute("rooms",rooms.findByActiveTrue());m.addAttribute("notifications",notices);m.addAttribute("registrationPending",registrationPending);m.addAttribute("openNotifications",openNotifications);return "customer-dashboard";}
 @PostMapping("/customer/reservations") public String reserve(Authentication auth,@RequestParam Long roomId,@RequestParam LocalDate checkIn,@RequestParam LocalDate checkOut,RedirectAttributes f){try{Account a=accounts.findByEmail(auth.getName()).orElseThrow();Room r=rooms.findById(roomId).orElseThrow();Reservation booking=service.create(a,r,checkIn,checkOut);boolean sent=email.sendReservationConfirmation(booking);f.addFlashAttribute("message",reservationMessage(booking.getId(),sent));f.addFlashAttribute("reservationId",booking.getId());}catch(Exception e){f.addFlashAttribute("error",e.getMessage());}return "redirect:/customer/dashboard";}
 @PostMapping("/customer/reservations/{id}/pay") public String pay(Authentication auth,@PathVariable Long id,@RequestParam String method,@RequestParam String paymentNumber,RedirectAttributes f){try{Account a=accounts.findByEmail(auth.getName()).orElseThrow();Reservation r=reservations.findById(id).orElseThrow();if(!r.getCustomer().getId().equals(a.getId()))throw new IllegalArgumentException("Reservation not found.");String digits=paymentNumber==null?"":paymentNumber.replaceAll("\\s","");if("SIMULATED_VISA".equals(method)&&!digits.matches("[0-9]{16}"))throw new IllegalArgumentException("Enter a 16-digit sample Visa number.");if("SIMULATED_GCASH".equals(method)&&!digits.matches("[0-9]{11}"))throw new IllegalArgumentException("Enter an 11-digit sample GCash number.");BigDecimal due=r.getAmountPaid().signum()==0?r.getRequiredDownPayment():r.getTotalPrice().subtract(r.getAmountPaid());PaymentRecord record=payment.simulatePayment(id,due,method);boolean sent=email.sendPaymentProof(record);f.addFlashAttribute("message",sent?"Simulated payment recorded. The receipt was emailed to "+a.getEmail()+".":"Simulated payment recorded. "+email.deliveryFailureMessage());}catch(Exception e){f.addFlashAttribute("error",e.getMessage());}return "redirect:/customer/dashboard";}
 @PostMapping("/customer/reservations/{id}/cancel") public String cancel(Authentication auth,@PathVariable Long id,RedirectAttributes f){Account a=accounts.findByEmail(auth.getName()).orElseThrow();Reservation r=reservations.findById(id).orElseThrow();if(!r.getCustomer().getId().equals(a.getId()))throw new IllegalArgumentException("Reservation not found.");if(!"PENDING".equals(r.getStatus())&& !"PAID".equals(r.getStatus()) && !"APPROVED".equals(r.getStatus())){f.addFlashAttribute("error","This reservation cannot be cancelled from its current status.");}else{r.setStatusBeforeCancellation(r.getStatus());r.setStatus("CANCELLATION_REQUESTED");reservations.save(r);email.sendReservationUpdate(r,"Your cancellation request was received and sent to management for review.");f.addFlashAttribute("message","Cancellation request sent to management. Refunds are not processed automatically.");}return "redirect:/customer/dashboard";}
 @GetMapping("/customer/contact") public String contact(Authentication auth,Model m){Account a=accounts.findByEmail(auth.getName()).orElseThrow();m.addAttribute("reports",reports.findByCustomerIdOrderByCreatedAtDesc(a.getId()));return "customer-contact";}
 @PostMapping("/customer/reports") public String report(Authentication auth,@RequestParam String subject,@RequestParam String message,RedirectAttributes f){Account a=accounts.findByEmail(auth.getName()).orElseThrow();reports.save(new CustomerReport(a,subject,message));f.addFlashAttribute("message","Your report was sent to hotel management.");return "redirect:/customer/contact";}

 @PostMapping("/customer/pencil-booking") public String pencilBooking(Authentication auth,@RequestParam Long roomId,@RequestParam LocalDate checkIn,@RequestParam LocalDate checkOut,RedirectAttributes f){try{Account a=accounts.findByEmail(auth.getName()).orElseThrow();Room room=rooms.findById(roomId).orElseThrow();Reservation b=service.create(a,room,checkIn,checkOut,"PENCIL");boolean sent=email.sendReservationConfirmation(b);f.addFlashAttribute("message",reservationMessage(b.getId(),sent)+" Management must review this pencil booking before payment.");}catch(Exception e){f.addFlashAttribute("error",e.getMessage());}return "redirect:/customer/dashboard";}
 @PostMapping("/customer/reservations/{id}/early-checkout") public String earlyCheckout(Authentication auth,@PathVariable Long id,RedirectAttributes f){Account a=accounts.findByEmail(auth.getName()).orElseThrow();Reservation r=reservations.findById(id).orElseThrow();if(!r.getCustomer().getId().equals(a.getId()))throw new IllegalArgumentException("Reservation not found.");if(!"APPROVED".equals(r.getStatus())){f.addFlashAttribute("error","Only approved reservations can request early checkout.");}else{r.setEarlyCheckoutRequested(true);reservations.save(r);email.sendReservationUpdate(r,"Your early checkout request was sent to onsite management for review.");f.addFlashAttribute("message","Early checkout request sent to onsite management.");}return "redirect:/customer/dashboard";}
 @PostMapping("/customer/reservations/{id}/extend") public String extend(Authentication auth,@PathVariable Long id,@RequestParam LocalDate newCheckOut,RedirectAttributes f){Account a=accounts.findByEmail(auth.getName()).orElseThrow();Reservation r=reservations.findById(id).orElseThrow();if(!r.getCustomer().getId().equals(a.getId()))throw new IllegalArgumentException("Reservation not found.");if(!"APPROVED".equals(r.getStatus())||!newCheckOut.isAfter(r.getCheckOut())){f.addFlashAttribute("error","Choose a later checkout date for an approved reservation.");}else{r.setRequestedCheckOut(newCheckOut);reservations.save(r);email.sendReservationUpdate(r,"Your checkout extension request was sent to management for review. Requested date: "+newCheckOut+".");f.addFlashAttribute("message","Extension request sent to management.");}return "redirect:/customer/dashboard";}
 @PostMapping("/customer/reservations/{id}/upgrade") public String upgrade(Authentication auth,@PathVariable Long id,@RequestParam Long roomId,RedirectAttributes f){Account a=accounts.findByEmail(auth.getName()).orElseThrow();Reservation r=reservations.findById(id).orElseThrow();if(!r.getCustomer().getId().equals(a.getId()))throw new IllegalArgumentException("Reservation not found.");Room target=rooms.findById(roomId).orElseThrow();if(!target.isActive()||target.getNightlyPrice().compareTo(r.getRoom().getNightlyPrice())<=0){f.addFlashAttribute("error","Choose an active room in a higher price category.");}else{r.setRequestedUpgradeRoomId(roomId);reservations.save(r);email.sendReservationUpdate(r,"Your room upgrade request was sent to management for review.");f.addFlashAttribute("message","Room upgrade request sent to management.");}return "redirect:/customer/dashboard";}
 @GetMapping("/customer/reservations/{id}/receipt") public String receipt(Authentication auth,@PathVariable Long id,Model m){Account a=accounts.findByEmail(auth.getName()).orElseThrow();Reservation r=reservations.findById(id).orElseThrow();if(!r.getCustomer().getId().equals(a.getId()))throw new IllegalArgumentException("Reservation not found.");m.addAttribute("reservation",r);m.addAttribute("payments",paymentRecords.findByReservation_IdOrderByCreatedAtAsc(id));m.addAttribute("nights",java.time.temporal.ChronoUnit.DAYS.between(r.getCheckIn(),r.getCheckOut()));m.addAttribute("balance",r.getTotalPrice().subtract(r.getAmountPaid()).max(BigDecimal.ZERO));return "receipt";}

 @PostMapping("/customer/reservations/{id}/email-proof") public String emailProof(Authentication auth,@PathVariable Long id,RedirectAttributes f){Account a=accounts.findByEmail(auth.getName()).orElseThrow();Reservation r=reservations.findById(id).orElseThrow();if(!r.getCustomer().getId().equals(a.getId()))throw new IllegalArgumentException("Reservation not found.");if(email.sendReservationProof(r))f.addFlashAttribute("message","Reservation proof #"+id+" was emailed to "+a.getEmail()+".");else f.addFlashAttribute("error",email.deliveryFailureMessage());return "redirect:/customer/dashboard";}

 private String reservationMessage(Long id,boolean sent){return sent?"Reservation #"+id+" created. Confirmation and reservation proof were emailed. Pay the 50% down payment from your dashboard.":"Reservation #"+id+" created. "+email.deliveryFailureMessage()+" Pay the 50% down payment from your dashboard.";}

}
